//! `amcrax`: command-line front end of the AmCraX engine.
//!
//! `verify <target>` compares the Rust engine with the golden tables generated by the Python
//! reference and can write the machine-readable comparison report.

mod bench;
mod verify;

use amcrax_engine::data::DataRoot;
use amcrax_engine::economics::reference::EconomicsData;
use amcrax_engine::economics::singapore::{Scenario, Summary, evaluate};
use amcrax_engine::kinetics::KineticsRegistry;
use amcrax_engine::props::FluidProps;
use amcrax_engine::reactor::{PfrInput, SolverOptions, simulate_pfr};
use amcrax_engine::studies::{GsaSetup, gsa_study, mc_singapore};
use amcrax_engine::verify as ev;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const USAGE: &str = "\
amcrax: AmCraX engine command-line interface

USAGE:
    amcrax --version
    amcrax --help
    amcrax verify <target> [--golden <dir>] [--root <repo>] [--report <file.json>]
                  [--props tables|coolprop]
    amcrax eval flowsheet --input <case.json> [--output <result.json>] [--eos ideal|pr]
                  [--props tables|coolprop] [--root <repo>]
    amcrax eval pfr --input <case.json> [--output <result.json>]
    amcrax eval economics --input <case.json> [--output <result.json>]
    amcrax study <name> [--root <repo>] [--output <result.json>] [--report <file.json>]
    amcrax bench [--items economics,pfr,gsa,kinetic] [--kinetic-draws M] [--threads 1,2,4]
                 [--root <repo>] [--output <timings.json>]

VERIFY TARGETS:
    numerics    golden tables of amcrax-numerics (default dir rust/golden/numerics)
    thermo      stage 1: data loading parity and thermodynamics (rust/golden/stage1)
    kinetics    stage 2: rate laws and viscosity (rust/golden/stage2)
    reactor     stage 2: plug-flow reactor and the derived searches (rust/golden/stage2)
    economics   stage 3: reference CAPEX, evaluate, break-even, legacy LCOH, stored results
                (rust/golden/stage3)
    carbon      stage 3: LCA factors, carbon intensity, carbon pricing (both modes), thresholds
    uq          stage 3: Sobol' estimators, bootstrap, Sobol' base samples, distributions
    stiff       stage 3: high-temperature (stiff) PFR cases against Python LSODA
    props       stage 4: the CoolProp back end against Python CoolProp on a dense grid
                (needs --props coolprop and a build with the `coolprop` feature)
    flowsheet   stage 4: run_python_case on every golden and stored case (rust/golden/stage4)
    heat        stage 4: pinch analysis on the Python and stored Aspen results, exchanger sizing,
                costing and break-even solves
    separation  stage 4: compression, PSA, Pd membrane (ODE, area search), purification helpers,
                compare_purification on the stored baseline results
    stage4      flowsheet, heat and separation in one report
    catalyst    stage 5: catalyst comparison (masses, LCOH curves and optima, design points,
                heat accounting on the stored Aspen results, stored catalyst_comparison files)
    stage5      every stage 5 target in one report
    all         every engine target above in one report (props excepted)
    studies     stage 3: run the Monte Carlo and the global sensitivity study and compare them with
                the stored Python results (about a minute)

    --root      repository root (default $AMCRAX_ROOT, else . or ..)
    --golden    golden-table directory (single-stage targets only)
    --report    write the comparison report (JSON: per quantity the number of cases, the maximum
                deviation, the gate, pass or fail)
    --props     fluid-property back end: tables (default; tabulated CoolProp values, exact only at
                the stored states) or coolprop (CoolProp 8.0.0 C++ library)

EVAL:
    flowsheet   read a CaseInputs JSON object (or {\"inputs\": {...}, \"eos\": \"ideal\"|\"pr\"}) and
                write the SimulationResult of Python run_python_case (source python_model; the
                engine is the Rust port), plus \"property_backend\"
    pfr         read a JSON object with the keyword arguments of Python simulate_pfr
                (catalyst_id, W_kg, T_in_C, P_in_bar, feed_kmol_h, mode, T_wall_C, U_W_m2K, eps_b,
                rho_particle_kg_m3, dp_m, tube_inner_diameter_m, n_tubes, pressure_drop,
                approach_factor, keq_basis, x_seed, n_points; unknown keys are an error) and write
                the result as JSON (stdout when --output is not given). Errors: JSON
                {\"error\": kind, \"message\": ...} and exit code 1.
    economics   read {\"summary\": {...} | \"result\": <stored SimulationResult>, \"scenario\": name or
                USD/t, \"overrides\": {...}} and write Python singapore.evaluate's dict

STUDY (writes the study's JSON; --report also compares it with the stored Python result):
    gsa                   scripts/research/uq_gsa_sobol.py (16 cases + dummy, N = 8192, 1000 bootstraps)
    kinetic-propagation   scripts/research/uq_kinetic_propagation.py (2 catalysts x C1, C2 x 4000 draws;
                          --threads N (default: all cores), --limit M (first M draws of each case));
                          always compared with the stored samples and summaries
    mc-singapore          scripts/research/economics_singapore.py Monte Carlo (5000 draws, 4 scenarios)
";

#[derive(Debug, PartialEq, Eq)]
enum Command {
    Version,
    Help,
    Verify {
        target: String,
        golden: Option<PathBuf>,
        root: Option<PathBuf>,
        report: Option<PathBuf>,
        props: Option<String>,
    },
    EvalFlowsheet {
        input: PathBuf,
        output: Option<PathBuf>,
        eos: Option<String>,
        props: Option<String>,
        root: Option<PathBuf>,
    },
    EvalPfr {
        input: PathBuf,
        output: Option<PathBuf>,
    },
    EvalEconomics {
        input: PathBuf,
        output: Option<PathBuf>,
    },
    Bench {
        root: Option<PathBuf>,
        items: Vec<String>,
        kinetic_draws: usize,
        threads: Vec<usize>,
        output: Option<PathBuf>,
    },
    Study {
        name: String,
        root: Option<PathBuf>,
        output: Option<PathBuf>,
        report: Option<PathBuf>,
        threads: Option<usize>,
        limit: Option<usize>,
    },
}

fn parse_args(args: &[String]) -> Result<Command, String> {
    let mut it = args.iter();
    match it.next().map(String::as_str) {
        None | Some("-h") | Some("--help") | Some("help") => Ok(Command::Help),
        Some("-V") | Some("--version") | Some("version") => Ok(Command::Version),
        Some("verify") => {
            let mut target = None;
            let mut golden = None;
            let mut root = None;
            let mut report = None;
            let mut props = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--props" => {
                        props = Some(
                            it.next()
                                .ok_or("--props needs tables or coolprop")?
                                .to_string(),
                        )
                    }
                    "--golden" => {
                        golden = Some(PathBuf::from(
                            it.next().ok_or("--golden needs a directory")?,
                        ))
                    }
                    "--root" => {
                        root = Some(PathBuf::from(it.next().ok_or("--root needs a directory")?))
                    }
                    "--report" => {
                        report = Some(PathBuf::from(it.next().ok_or("--report needs a file")?))
                    }
                    s if s.starts_with('-') => return Err(format!("unknown option {s}")),
                    s => {
                        if target.is_some() {
                            return Err(format!("unexpected argument {s}"));
                        }
                        target = Some(s.to_string());
                    }
                }
            }
            let target =
                target.ok_or("verify needs a target (numerics, thermo, kinetics, reactor, all)")?;
            Ok(Command::Verify {
                target,
                golden,
                root,
                report,
                props,
            })
        }
        Some("bench") => {
            let (mut root, mut output) = (None, None);
            let mut items = Vec::new();
            let mut kinetic_draws = 25usize;
            let mut threads = vec![1usize];
            while let Some(a) = it.next() {
                let mut val = |n: &str| -> Result<String, String> {
                    it.next().cloned().ok_or(format!("{n} needs a value"))
                };
                match a.as_str() {
                    "--root" => root = Some(PathBuf::from(val("--root")?)),
                    "--output" => output = Some(PathBuf::from(val("--output")?)),
                    "--items" => items = val("--items")?.split(',').map(str::to_string).collect(),
                    "--kinetic-draws" => {
                        kinetic_draws = val("--kinetic-draws")?
                            .parse()
                            .map_err(|_| "--kinetic-draws needs a number")?
                    }
                    "--threads" => {
                        threads = val("--threads")?
                            .split(',')
                            .map(|x| x.parse::<usize>())
                            .collect::<Result<_, _>>()
                            .map_err(|_| "--threads needs numbers, e.g. 1,2,4")?
                    }
                    s => return Err(format!("unexpected argument {s}")),
                }
            }
            Ok(Command::Bench {
                root,
                items,
                kinetic_draws,
                threads,
                output,
            })
        }
        Some("study") => {
            let name = it
                .next()
                .ok_or("study needs a name (gsa, mc-singapore)")?
                .to_string();
            let (mut root, mut output, mut report) = (None, None, None);
            let (mut threads, mut limit) = (None, None);
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--root" => {
                        root = Some(PathBuf::from(it.next().ok_or("--root needs a directory")?))
                    }
                    "--output" => {
                        output = Some(PathBuf::from(it.next().ok_or("--output needs a file")?))
                    }
                    "--report" => {
                        report = Some(PathBuf::from(it.next().ok_or("--report needs a file")?))
                    }
                    "--threads" => {
                        threads = Some(
                            it.next()
                                .and_then(|x| x.parse().ok())
                                .ok_or("--threads needs a number")?,
                        )
                    }
                    "--limit" => {
                        limit = Some(
                            it.next()
                                .and_then(|x| x.parse().ok())
                                .ok_or("--limit needs a number")?,
                        )
                    }
                    s => return Err(format!("unexpected argument {s}")),
                }
            }
            Ok(Command::Study {
                name,
                root,
                output,
                report,
                threads,
                limit,
            })
        }
        Some("eval") => {
            let model = match it.next().map(String::as_str) {
                Some(m @ ("pfr" | "economics" | "flowsheet")) => m.to_string(),
                Some(other) => {
                    return Err(format!(
                        "unknown eval model {other} (available: pfr, economics, flowsheet)"
                    ));
                }
                None => return Err("eval needs a model (pfr, economics, flowsheet)".into()),
            };
            let mut input = None;
            let mut output = None;
            let (mut eos, mut props, mut root) = (None, None, None);
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--input" => {
                        input = Some(PathBuf::from(it.next().ok_or("--input needs a file")?))
                    }
                    "--output" => {
                        output = Some(PathBuf::from(it.next().ok_or("--output needs a file")?))
                    }
                    "--eos" if model == "flowsheet" => {
                        eos = Some(it.next().ok_or("--eos needs ideal or pr")?.to_string())
                    }
                    "--props" if model == "flowsheet" => {
                        props = Some(
                            it.next()
                                .ok_or("--props needs tables or coolprop")?
                                .to_string(),
                        )
                    }
                    "--root" if model == "flowsheet" => {
                        root = Some(PathBuf::from(it.next().ok_or("--root needs a directory")?))
                    }
                    s => return Err(format!("unexpected argument {s}")),
                }
            }
            let input = input.ok_or("eval needs --input <case.json>")?;
            Ok(match model.as_str() {
                "pfr" => Command::EvalPfr { input, output },
                "economics" => Command::EvalEconomics { input, output },
                _ => Command::EvalFlowsheet {
                    input,
                    output,
                    eos,
                    props,
                    root,
                },
            })
        }
        Some(other) => Err(format!("unknown command {other}")),
    }
}

fn default_golden_dir(root: &Path, name: &str) -> PathBuf {
    let p = root.join("rust").join("golden").join(name);
    if p.is_dir() {
        return p;
    }
    let alt = PathBuf::from("golden").join(name);
    if alt.is_dir() { alt } else { p }
}

fn write_report(path: &Path, reports: &[ev::Report]) -> Result<(), String> {
    let mut meta = BTreeMap::new();
    meta.insert(
        "engine_version".to_string(),
        serde_json::Value::String(amcrax_engine::ENGINE_VERSION.to_string()),
    );
    for k in [
        "GITHUB_RUN_ID",
        "GITHUB_SHA",
        "GITHUB_REF_NAME",
        "RUNNER_OS",
    ] {
        if let Ok(v) = std::env::var(k) {
            meta.insert(k.to_lowercase(), serde_json::Value::String(v));
        }
    }
    if let Some(dir) = path.parent()
        && !dir.as_os_str().is_empty()
    {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(path, ev::report_json(reports, meta) + "\n").map_err(|e| e.to_string())
}

#[cfg(feature = "coolprop")]
fn coolprop_backend() -> Result<Box<dyn FluidProps>, String> {
    let b = amcrax_coolprop::CoolPropBackend::new().map_err(|e| e.to_string())?;
    eprintln!("CoolProp back end: version {}", b.version());
    Ok(Box::new(b))
}

#[cfg(not(feature = "coolprop"))]
fn coolprop_backend() -> Result<Box<dyn FluidProps>, String> {
    Err("this amcrax was built without the `coolprop` feature (use --props tables)".into())
}

#[cfg(feature = "coolprop")]
fn coolprop_notice() -> String {
    format!(
        "CoolProp linked: {}; licence of the linked CoolProp: {}",
        amcrax_coolprop::linked(),
        amcrax_coolprop::licence()
            .lines()
            .take(3)
            .collect::<Vec<_>>()
            .join(" / ")
    )
}

#[cfg(not(feature = "coolprop"))]
fn coolprop_notice() -> String {
    "CoolProp not compiled in".into()
}

/// The fluid-property back end: `tables` (default; tabulated CoolProp values, exact only at the
/// stored states) or `coolprop` (C++ library, feature `coolprop`).
fn make_backend(kind: Option<&str>, root: &Path) -> Result<Box<dyn FluidProps>, String> {
    make_backend_in(kind, root, "stage4")
}

/// As [`make_backend`], the tables back end from the golden directory `stage` (stage 5 records
/// the additional states its studies visit).
fn make_backend_in(
    kind: Option<&str>,
    root: &Path,
    stage: &str,
) -> Result<Box<dyn FluidProps>, String> {
    match kind.unwrap_or("tables") {
        "tables" => {
            let g =
                ev::Golden::open(&default_golden_dir(root, stage)).map_err(|e| e.to_string())?;
            Ok(Box::new(
                ev::stage4::tables_backend(&g).map_err(|e| e.to_string())?,
            ))
        }
        "coolprop" => coolprop_backend(),
        other => Err(format!(
            "unknown property back end {other} (tables, coolprop)"
        )),
    }
}

/// `amcrax eval flowsheet`: JSON case in (a CaseInputs object, or {"inputs": {...}, "eos": ...}),
/// JSON SimulationResult out.
fn eval_flowsheet(
    input: &Path,
    output: Option<&Path>,
    eos: Option<&str>,
    props: Option<&str>,
    root: &Path,
) -> ExitCode {
    use amcrax_engine::process::{CaseInputs, eos_from_name, run_python_case};
    let result = (|| -> Result<serde_json::Value, (String, String)> {
        let v = read_value(input).map_err(|e| ("input".to_string(), e))?;
        let (inp, eos_name) = match v.get("inputs") {
            Some(i) => (
                i.clone(),
                v.get("eos").and_then(|e| e.as_str()).map(str::to_string),
            ),
            None => (v.clone(), None),
        };
        let eos_name = eos_name
            .or(eos.map(str::to_string))
            .unwrap_or_else(|| "ideal".into());
        let ci = CaseInputs::from_value(&inp)
            .map_err(|e| (error_kind(&e).to_string(), e.to_string()))?;
        let eos =
            eos_from_name(&eos_name).map_err(|e| (error_kind(&e).to_string(), e.to_string()))?;
        let b = make_backend(props, root).map_err(|e| ("property".to_string(), e))?;
        let r = run_python_case(&ci, eos, b.as_ref())
            .map_err(|e| (error_kind(&e).to_string(), e.to_string()))?;
        let mut j = r.to_json();
        j["property_backend"] = serde_json::Value::String(b.backend().to_string());
        Ok(j)
    })();
    let (v, code) = match result {
        Ok(v) => (v, ExitCode::SUCCESS),
        Err((kind, msg)) => (
            serde_json::json!({"error": kind, "message": msg}),
            ExitCode::FAILURE,
        ),
    };
    if let Err(e) = write_json(output, &v) {
        eprintln!("amcrax eval flowsheet: cannot write output: {e}");
        return ExitCode::from(2);
    }
    code
}

fn run_engine_target(
    target: &str,
    root: &Path,
    golden: Option<PathBuf>,
    props: Option<&str>,
) -> Result<Vec<ev::Report>, String> {
    let s = |e: amcrax_engine::EngineError| e.to_string();
    let reg = KineticsRegistry::embedded();
    let sopt = SolverOptions::default();
    let stage = |name: &str| -> Result<ev::Golden, String> {
        let dir = match (&golden, target) {
            (Some(g), t) if t != "all" => g.clone(),
            _ => default_golden_dir(root, name),
        };
        ev::Golden::open(&dir).map_err(s)
    };
    let mut out = Vec::new();
    if matches!(target, "thermo" | "all") {
        let g = stage("stage1")?;
        out.push(ev::stage1::data(&DataRoot::new(root), &g).map_err(s)?);
        out.push(ev::stage1::thermo(&g).map_err(s)?);
    }
    if matches!(target, "kinetics" | "all") {
        out.push(ev::stage2::kinetics(&stage("stage2")?, reg).map_err(s)?);
    }
    if matches!(target, "reactor" | "all") {
        out.push(ev::stage2::reactor(&stage("stage2")?, reg, &sopt).map_err(s)?);
    }
    if matches!(target, "economics" | "all") {
        out.push(
            ev::stage3::economics(&stage("stage3")?, EconomicsData::embedded(), root).map_err(s)?,
        );
    }
    if matches!(target, "stiff" | "all") {
        out.push(ev::stage3::stiff(&stage("stage3")?, reg, &sopt).map_err(s)?);
    }
    if matches!(target, "uq" | "all") {
        out.push(ev::stage3::uq(&stage("stage3")?).map_err(s)?);
    }
    if target == "studies" {
        let d = EconomicsData::embedded();
        let base = read_value(&root.join("results/simulations/baseline.json"))?;
        let s_hi = Summary::extract(&base).map_err(s)?;
        let (mc, grey) = mc_singapore(d, &s_hi, 5000).map_err(s)?;
        let gsa = run_gsa(root)?;
        out.push(
            ev::stage3::studies(&stage("stage3")?, d, root, Some(&gsa), Some((&mc, &grey)))
                .map_err(s)?,
        );
    }
    if matches!(target, "carbon" | "all") {
        out.push(
            ev::stage3::carbon(
                &stage("stage3")?,
                EconomicsData::embedded(),
                amcrax_engine::carbon::embedded_factors(),
                root,
            )
            .map_err(s)?,
        );
    }
    if target == "props" {
        if props != Some("coolprop") {
            return Err("verify props compares the CoolProp back end: use --props coolprop".into());
        }
        let b = make_backend(props, root)?;
        let mut r = ev::stage4::props(&stage("stage4")?, b.as_ref()).map_err(s)?;
        r.findings.push(coolprop_notice());
        out.push(r);
    }
    if matches!(target, "flowsheet" | "all" | "stage4") {
        let b = make_backend(props, root)?;
        out.push(ev::stage4::flowsheet(&stage("stage4")?, b.as_ref(), root).map_err(s)?);
    }
    if matches!(target, "separation" | "all" | "stage4") {
        out.push(
            ev::stage4::separation(
                &stage("stage4")?,
                amcrax_engine::separation::SepParams::embedded(),
                root,
            )
            .map_err(s)?,
        );
    }
    if matches!(target, "heat" | "all" | "stage4") {
        let b = make_backend(props, root)?;
        out.push(
            ev::stage4::heat(
                &stage("stage4")?,
                b.as_ref(),
                EconomicsData::embedded(),
                root,
            )
            .map_err(s)?,
        );
    }
    if matches!(target, "catalyst" | "stage5" | "all") {
        let b = make_backend_in(props, root, "stage5")?;
        let ctx = amcrax_engine::catalyst::Ctx {
            reg,
            sopt,
            econ: EconomicsData::embedded(),
            props: b.as_ref(),
        };
        out.push(ev::stage5::catalyst(&stage("stage5")?, &ctx, root).map_err(s)?);
    }
    if out.is_empty() {
        return Err(format!(
            "unknown target {target} (available: numerics, thermo, kinetics, reactor, economics, carbon, uq, \
             flowsheet, props, all, studies)"
        ));
    }
    Ok(out)
}

fn read_value(p: &Path) -> Result<serde_json::Value, String> {
    let b = std::fs::read(p).map_err(|e| format!("{}: {e}", p.display()))?;
    serde_json::from_slice(&b).map_err(|e| format!("{}: {e}", p.display()))
}

/// The global sensitivity study on the stored Aspen baselines (heat integration on and off).
fn run_gsa(root: &Path) -> Result<serde_json::Value, String> {
    let s = |e: amcrax_engine::EngineError| e.to_string();
    let d = EconomicsData::embedded();
    let tornado = read_value(&root.join("results/research/singapore/tornado.json"))?;
    let st = GsaSetup::new(d, &tornado).map_err(s)?;
    let mut sums = Vec::new();
    for (name, file) in [
        ("heat_integration_on", "results/simulations/baseline.json"),
        (
            "heat_integration_off",
            "results/simulations/baseline_no_hi.json",
        ),
    ] {
        sums.push((
            name.to_string(),
            Summary::extract(&read_value(&root.join(file))?).map_err(s)?,
        ));
    }
    gsa_study(&st, &sums).map_err(s)
}

fn write_json(path: Option<&Path>, v: &serde_json::Value) -> Result<(), String> {
    let text = serde_json::to_string_pretty(v).unwrap_or_default();
    match path {
        Some(p) => {
            if let Some(dir) = p.parent()
                && !dir.as_os_str().is_empty()
            {
                std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
            }
            std::fs::write(p, text + "\n").map_err(|e| e.to_string())
        }
        None => {
            println!("{text}");
            Ok(())
        }
    }
}

/// `amcrax study <name>`.
fn study(name: &str, root: &Path, output: Option<&Path>, report: Option<&Path>) -> ExitCode {
    let s = |e: amcrax_engine::EngineError| e.to_string();
    let t0 = std::time::Instant::now();
    let d = EconomicsData::embedded();
    let res: Result<(serde_json::Value, Option<ev::Report>), String> = (|| match name {
        "gsa" => {
            let g = run_gsa(root)?;
            let r = if report.is_some() {
                let golden = ev::Golden::open(&default_golden_dir(root, "stage3")).map_err(s)?;
                Some(ev::stage3::studies(&golden, d, root, Some(&g), None).map_err(s)?)
            } else {
                None
            };
            Ok((g, r))
        }
        "mc-singapore" => {
            let base = read_value(&root.join("results/simulations/baseline.json"))?;
            let s_hi = Summary::extract(&base).map_err(s)?;
            let (mc, grey) = mc_singapore(d, &s_hi, 5000).map_err(s)?;
            let r = if report.is_some() {
                let golden = ev::Golden::open(&default_golden_dir(root, "stage3")).map_err(s)?;
                Some(ev::stage3::studies(&golden, d, root, None, Some((&mc, &grey))).map_err(s)?)
            } else {
                None
            };
            Ok((
                serde_json::json!({"source_type": "rust", "seed": 20261123, "n_samples": 5000,
                                   "results": mc, "samples_lcoh_grey": grey}),
                r,
            ))
        }
        other => Err(format!(
            "unknown study {other} (available: gsa, mc-singapore)"
        )),
    })();
    match res {
        Err(e) => {
            eprintln!("amcrax study {name}: {e}");
            ExitCode::from(2)
        }
        Ok((v, rep)) => {
            eprintln!("amcrax study {name}: {:.2} s", t0.elapsed().as_secs_f64());
            if let Err(e) = write_json(output, &v) {
                eprintln!("amcrax study {name}: cannot write output: {e}");
                return ExitCode::from(2);
            }
            match (rep, report) {
                (Some(r), Some(p)) => {
                    print!("{}", r.render());
                    if let Err(e) = write_report(p, std::slice::from_ref(&r)) {
                        eprintln!("amcrax study: cannot write report: {e}");
                        return ExitCode::from(2);
                    }
                    if r.passed() {
                        ExitCode::SUCCESS
                    } else {
                        ExitCode::FAILURE
                    }
                }
                _ => ExitCode::SUCCESS,
            }
        }
    }
}

/// `amcrax study kinetic-propagation`.
fn kinetic_study(
    root: &Path,
    output: Option<&Path>,
    report: Option<&Path>,
    threads: Option<usize>,
    limit: Option<usize>,
) -> ExitCode {
    use amcrax_engine::studies::kinetic::{KP_CATS, KpSetup, case_summary, kinetic_propagation};
    let threads = threads.unwrap_or_else(|| {
        std::thread::available_parallelism()
            .map(std::num::NonZeroUsize::get)
            .unwrap_or(1)
    });
    let run = || -> Result<(serde_json::Value, ev::Report), String> {
        let s = |e: amcrax_engine::EngineError| e.to_string();
        let reg = KineticsRegistry::embedded();
        let ky = amcrax_engine::odata::OValue::from_yaml(
            "kinetics.yaml",
            amcrax_engine::kinetics::EMBEDDED_YAML,
        )
        .map_err(s)?;
        let st = KpSetup::new(reg, &ky).map_err(s)?;
        let t0 = std::time::Instant::now();
        let mut nominal = Vec::new();
        for k in 0..KP_CATS.len() {
            nominal.push(st.run_draw(k, None).map_err(s)?);
        }
        let res = kinetic_propagation(&st, 4000, limit, threads).map_err(s)?;
        let secs = t0.elapsed().as_secs_f64();
        let (mut n_pfr, mut n_stiff) = (0usize, 0usize);
        let mut cats = serde_json::Map::new();
        for (cid, cases, rate) in &res {
            let t_lab = KP_CATS
                .iter()
                .find(|c| c.0 == cid)
                .map(|c| c.2)
                .unwrap_or([0.0; 3]);
            let mut cs = serde_json::Map::new();
            for (case, draws, outs) in cases {
                if case != "C3" {
                    n_pfr += outs.iter().map(|o| o.n_pfr).sum::<usize>();
                    n_stiff += outs.iter().map(|o| o.n_stiff).sum::<usize>();
                }
                let mut v = case_summary(draws, outs, &t_lab);
                if let Some(m) = v.as_object_mut() {
                    m.insert(
                        "draws".into(),
                        serde_json::json!(draws
                            .iter()
                            .zip(outs)
                            .map(|(d, o)| serde_json::json!({"params": d, "X_lab": o.x_lab,
                                "T_req": o.t_req.iter().map(|x| x.0).collect::<Vec<_>>(), "m_frac99": o.m_frac99}))
                            .collect::<Vec<_>>()),
                    );
                }
                cs.insert(case.clone(), v);
            }
            cats.insert(
                cid.clone(),
                serde_json::json!({"C3_acceptance_rate": rate, "cases": cs}),
            );
        }
        eprintln!(
            "kinetic propagation: {n_pfr} PFR solves ({n_stiff} with the Radau fallback) on {threads} thread(s) in {secs:.1} s"
        );
        let r = ev::stage3::kinetic(root, &res, &nominal, limit.is_none()).map_err(s)?;
        Ok((
            serde_json::json!({"source_type": "rust", "threads": threads, "limit": limit, "seconds": secs,
                               "n_pfr_solves": n_pfr, "n_stiff_fallback": n_stiff, "catalysts": cats}),
            r,
        ))
    };
    match run() {
        Err(e) => {
            eprintln!("amcrax study kinetic-propagation: {e}");
            ExitCode::from(2)
        }
        Ok((v, r)) => {
            if let Err(e) = write_json(output, &v) {
                eprintln!("amcrax study: cannot write output: {e}");
                return ExitCode::from(2);
            }
            print!("{}", r.render());
            if let Some(p) = report
                && let Err(e) = write_report(p, std::slice::from_ref(&r))
            {
                eprintln!("amcrax study: cannot write report: {e}");
                return ExitCode::from(2);
            }
            if r.passed() {
                ExitCode::SUCCESS
            } else {
                ExitCode::FAILURE
            }
        }
    }
}

/// `amcrax eval economics`: JSON case in, the `evaluate` dict out.
fn eval_economics(input: &Path, output: Option<&Path>) -> ExitCode {
    let res = read_value(input).and_then(|c| {
        let s = if c.get("summary").is_some() {
            Summary::from_summary_json(&c["summary"])
        } else {
            Summary::extract(&c["result"])
        }
        .map_err(|e| e.to_string())?;
        let scenario = if c["scenario"].is_null() {
            Scenario::Named("grey".into())
        } else {
            Scenario::from_json(&c["scenario"]).map_err(|e| e.to_string())?
        };
        let o = c["overrides"].as_object().cloned().unwrap_or_default();
        evaluate(EconomicsData::embedded(), &s, &scenario, &o).map_err(|e| e.to_string())
    });
    match res {
        Ok(v) => match write_json(output, &v) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("amcrax eval economics: {e}");
                ExitCode::from(2)
            }
        },
        Err(e) => {
            let _ = write_json(
                output,
                &serde_json::json!({"error": "domain", "message": e}),
            );
            ExitCode::FAILURE
        }
    }
}

fn error_kind(e: &amcrax_engine::EngineError) -> &'static str {
    use amcrax_engine::EngineError as E;
    match e {
        E::Spec(_) => "spec",
        E::Bracket(_) => "bracket",
        E::Integration(_) => "integration",
        E::Domain(_) => "domain",
        E::Data { .. } => "data",
        E::Property(_) => "property",
        E::Numerical(_) => "numerical",
    }
}

/// `amcrax eval pfr`: JSON case in, JSON result out.
fn eval_pfr(input: &Path, output: Option<&Path>) -> ExitCode {
    let write = |text: String| -> Result<(), String> {
        match output {
            Some(p) => std::fs::write(p, text + "\n").map_err(|e| e.to_string()),
            None => {
                println!("{text}");
                Ok(())
            }
        }
    };
    let result = std::fs::read(input)
        .map_err(|e| ("input".to_string(), format!("{}: {e}", input.display())))
        .and_then(|b| {
            serde_json::from_slice::<PfrInput>(&b)
                .map_err(|e| ("input".to_string(), format!("{}: {e}", input.display())))
        })
        .and_then(|case| {
            simulate_pfr(
                KineticsRegistry::embedded(),
                &case,
                &SolverOptions::default(),
            )
            .map_err(|e| (error_kind(&e).to_string(), e.to_string()))
        });
    let (text, code) = match result {
        Ok(r) => (
            serde_json::to_string_pretty(&r).unwrap_or_default(),
            ExitCode::SUCCESS,
        ),
        Err((kind, msg)) => (
            serde_json::json!({"error": kind, "message": msg}).to_string(),
            ExitCode::FAILURE,
        ),
    };
    if let Err(e) = write(text) {
        eprintln!("amcrax eval pfr: cannot write output: {e}");
        return ExitCode::from(2);
    }
    code
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(&args) {
        Ok(Command::Version) => {
            println!("amcrax {}", amcrax_engine::ENGINE_VERSION);
            ExitCode::SUCCESS
        }
        Ok(Command::Help) => {
            print!("{USAGE}");
            ExitCode::SUCCESS
        }
        Ok(Command::EvalPfr { input, output }) => eval_pfr(&input, output.as_deref()),
        Ok(Command::EvalEconomics { input, output }) => eval_economics(&input, output.as_deref()),
        Ok(Command::Bench {
            root,
            items,
            kinetic_draws,
            threads,
            output,
        }) => {
            let root = root.unwrap_or_else(ev::default_repo_root);
            match bench::run(&root, &items, kinetic_draws, &threads) {
                Ok(v) => match write_json(output.as_deref(), &v) {
                    Ok(()) => ExitCode::SUCCESS,
                    Err(e) => {
                        eprintln!("amcrax bench: {e}");
                        ExitCode::from(2)
                    }
                },
                Err(e) => {
                    eprintln!("amcrax bench: {e}");
                    ExitCode::from(2)
                }
            }
        }
        Ok(Command::Study {
            name,
            root,
            output,
            report,
            threads,
            limit,
        }) => {
            let root = root.unwrap_or_else(ev::default_repo_root);
            if name == "kinetic-propagation" {
                return kinetic_study(&root, output.as_deref(), report.as_deref(), threads, limit);
            }
            study(&name, &root, output.as_deref(), report.as_deref())
        }
        Ok(Command::EvalFlowsheet {
            input,
            output,
            eos,
            props,
            root,
        }) => {
            let root = root.unwrap_or_else(ev::default_repo_root);
            eval_flowsheet(
                &input,
                output.as_deref(),
                eos.as_deref(),
                props.as_deref(),
                &root,
            )
        }
        Ok(Command::Verify {
            target,
            golden,
            root,
            report,
            props,
        }) => {
            let root = root.unwrap_or_else(ev::default_repo_root);
            if target == "numerics" {
                let dir = golden.unwrap_or_else(|| default_golden_dir(&root, "numerics"));
                return match verify::numerics(&dir) {
                    Ok(r) => {
                        print!("{}", r.render());
                        if r.passed() {
                            ExitCode::SUCCESS
                        } else {
                            ExitCode::FAILURE
                        }
                    }
                    Err(e) => {
                        eprintln!("amcrax verify numerics: {e}");
                        ExitCode::from(2)
                    }
                };
            }
            match run_engine_target(&target, &root, golden, props.as_deref()) {
                Ok(reports) => {
                    for r in &reports {
                        print!("{}", r.render());
                    }
                    if let Some(p) = report {
                        if let Err(e) = write_report(&p, &reports) {
                            eprintln!("amcrax verify: cannot write report {}: {e}", p.display());
                            return ExitCode::from(2);
                        }
                        println!("report written to {}", p.display());
                    }
                    if reports.iter().all(ev::Report::passed) {
                        ExitCode::SUCCESS
                    } else {
                        ExitCode::FAILURE
                    }
                }
                Err(e) => {
                    eprintln!("amcrax verify {target}: {e}");
                    ExitCode::from(2)
                }
            }
        }
        Err(e) => {
            eprintln!("amcrax: {e}\n\n{USAGE}");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn parses_commands() {
        assert_eq!(parse_args(&args(&["--version"])), Ok(Command::Version));
        assert_eq!(parse_args(&args(&[])), Ok(Command::Help));
        assert_eq!(
            parse_args(&args(&["verify", "numerics", "--golden", "g"])),
            Ok(Command::Verify {
                target: "numerics".into(),
                golden: Some(PathBuf::from("g")),
                root: None,
                report: None,
                props: None,
            })
        );
        assert_eq!(
            parse_args(&args(&["verify", "thermo", "--report", "r.json"])),
            Ok(Command::Verify {
                target: "thermo".into(),
                golden: None,
                root: None,
                report: Some(PathBuf::from("r.json")),
                props: None,
            })
        );
        assert_eq!(
            parse_args(&args(&["eval", "pfr", "--input", "c.json"])),
            Ok(Command::EvalPfr {
                input: PathBuf::from("c.json"),
                output: None,
            })
        );
        assert!(parse_args(&args(&["eval", "pfr"])).is_err());
        assert_eq!(
            parse_args(&args(&[
                "eval",
                "flowsheet",
                "--input",
                "c.json",
                "--eos",
                "pr"
            ])),
            Ok(Command::EvalFlowsheet {
                input: PathBuf::from("c.json"),
                output: None,
                eos: Some("pr".into()),
                props: None,
                root: None,
            })
        );
        assert!(parse_args(&args(&["eval", "nope", "--input", "c.json"])).is_err());
        assert!(parse_args(&args(&["verify"])).is_err());
        assert!(parse_args(&args(&["verify", "a", "b"])).is_err());
        assert!(parse_args(&args(&["frobnicate"])).is_err());
    }
}
